export const meta = {
  name: 'alpha-beta-join',
  description: 'Gather "alpha" and "beta" from two Haiku agents in parallel, then join them with a dash',
  phases: [
    { title: 'gather', detail: 'two parallel agents reply alpha and beta' },
    { title: 'join', detail: 'one agent joins both answers with a dash' },
  ],
}

phase('gather')
const [a, b] = await parallel([
  () => agent('Reply with only the word alpha. No other text.', { label: 'gather:alpha', phase: 'gather', model: 'haiku' }),
  () => agent('Reply with only the word beta. No other text.', { label: 'gather:beta', phase: 'gather', model: 'haiku' }),
])

phase('join')
const joined = await agent(
  `Two answers were gathered: first "${a}", second "${b}". Reply with them joined by a dash, in that order, and nothing else. Example format: X-Y`,
  { label: 'join', phase: 'join', model: 'haiku' }
)

return joined

